336	/// Chunk-wise GDR prefill operator contract for Qwen3.5.
337	///
338	/// The chunk-wise path is an explicit multi-stage operator with pre-allocated
339	/// scratch instead of one opaque kernel launch.
340	#[allow(clippy::too_many_arguments)]
341	pub fn gated_delta_rule_prefill_chunkwise_into(
342	    ctx: &DeviceContext,
343	    qkv: &HiddenStates,
344	    b_proj: &HiddenStates,
345	    a_proj: &HiddenStates,
346	    dt_bias: &DeviceVec,
347	    a_log: &CudaSlice<f32>,
348	    state: &mut CudaSlice<f32>,
349	    scratch: &mut GdrChunkwiseScratch35,
350	    output: &mut HiddenStates,
351	    num_key_heads: usize,
352	    num_value_heads: usize,
353	    key_dim: usize,
354	    val_dim: usize,
355	) -> Result<()> {
356	    assert_eq!(scratch.q_expanded.seq_len, qkv.seq_len);
357	    assert_eq!(scratch.k_expanded.seq_len, qkv.seq_len);
358	    assert_eq!(scratch.v_raw.seq_len, qkv.seq_len);
359	    assert_eq!(scratch.w.seq_len, qkv.seq_len);
360	    assert_eq!(scratch.u.seq_len, qkv.seq_len);
361	    assert_eq!(scratch.v_new.seq_len, qkv.seq_len);
362	    assert_eq!(scratch.q_expanded.hidden_dim, num_value_heads * key_dim);
363	    assert_eq!(scratch.k_expanded.hidden_dim, num_value_heads * key_dim);
364	    assert_eq!(scratch.v_raw.hidden_dim, num_value_heads * val_dim);
365	    assert_eq!(scratch.w.hidden_dim, num_value_heads * key_dim);
366	    assert_eq!(scratch.u.hidden_dim, num_value_heads * val_dim);
367	    assert_eq!(scratch.v_new.hidden_dim, num_value_heads * val_dim);
368	
369	    let expected_gate_len = qkv.seq_len * num_value_heads;
370	    let expected_chunk_a_len = qkv.seq_len * num_value_heads * GdrChunkwiseScratch35::CHUNK_SIZE;
371	    let expected_chunk_ai_len = expected_chunk_a_len;
372	    let expected_chunk_state_len =
373	        GdrChunkwiseScratch35::num_chunks(qkv.seq_len) * num_value_heads * val_dim * key_dim;
374	    assert_eq!(scratch.g_cumsum.len(), expected_gate_len);
375	    assert_eq!(scratch.beta.len(), expected_gate_len);
376	    assert_eq!(scratch.a_tril.len(), expected_chunk_a_len);
377	    assert_eq!(scratch.a_inv.len(), expected_chunk_ai_len);
378	    assert_eq!(scratch.chunk_state.len(), expected_chunk_state_len);
379	
380	    gated_delta_rule_prefill_chunk_prepare_into(
381	        ctx,
382	        qkv,
383	        b_proj,
384	        a_proj,
