616	    /// One decode step of the conv1d kernel's documented recurrence:
617	    /// `silu(bf16(Σ_k w[k] * [state[0], state[1], state[2], x]))`, followed by
618	    /// shifting the state to the previous inputs, oldest first.
619	    fn reference_conv1d_decode_step(x: &[bf16], weights: &[bf16], state: &mut [f32]) -> Vec<bf16> {
620	        let channels = x.len();
621	        let kernel_size = weights.len() / channels;
622	        let width = kernel_size - 1;
623	        let mut out = vec![bf16::ZERO; channels];
624	        for c in 0..channels {
625	            let mut sum = 0.0f32;
626	            for k in 0..kernel_size {
627	                let value = if k == kernel_size - 1 {
628	                    x[c].to_f32()
629	                } else {
630	                    state[c * width + k]
631	                };
632	                sum += value * weights[c * kernel_size + k].to_f32();
633	            }
634	            let sum_bf16 = bf16::from_f32(sum).to_f32();
635	            out[c] = bf16::from_f32(sum_bf16 / (1.0 + (-sum_bf16).exp()));
636	        }
637	        for c in 0..channels {
638	            for i in 0..width {
639	                state[c * width + i] = if i + 1 < width {
640	                    state[c * width + i + 1]
641	                } else {
642	                    x[c].to_f32()
643	                };
644	            }
645	        }
646	        out
647	    }
