649	    /// Steps between two finite bf16 values on the bf16 grid, with +0 and -0 as
650	    /// one point.
651	    fn bf16_ulp_distance(a: bf16, b: bf16) -> u32 {
652	        let ordered = |value: bf16| {
653	            let bits = i32::from(value.to_bits());
654	            if bits & 0x8000 != 0 {
655	                -(bits & 0x7fff)
656	            } else {
657	                bits
658	            }
659	        };
660	        ordered(a).abs_diff(ordered(b))
661	    }
