664	    fn conv1d_decode_batch_matches_reference_steps() -> Result<()> {
665	        let ctx = DeviceContext::new()?;
666	        let num_channels = 10240usize;
667	        let kernel_size = 4usize;
668	        let state_width = kernel_size - 1;
669	        let batch_size = 3usize;
670	
671	        let w_host = bf16_vec(
672	            &(0..num_channels * kernel_size)
673	                .map(|i| ((i % 37) as f32 - 18.0) * 0.015_625)
674	                .collect::<Vec<_>>(),
675	        );
676	        let conv_weight = DeviceVec::from_host(&ctx, &w_host)?;
677	
678	        // Distinct initial states with identical inputs: a shared or mis-indexed
679	        // state pointer would make slots 1 and 2 drift from their own reference.
680	        let state_len = num_channels * state_width;
681	        let initial: Vec<Vec<bf16>> = (0..batch_size)
682	            .map(|slot| {
683	                bf16_vec(
684	                    &(0..state_len)
685	                        .map(|i| ((i + slot * 7) % 23) as f32 * 0.01 - 0.11)
686	                        .collect::<Vec<_>>(),
687	                )
688	            })
689	            .collect();
690	        let mut host_states: Vec<Vec<f32>> = initial
691	            .iter()
692	            .map(|values| values.iter().map(|value| value.to_f32()).collect())
693	            .collect();
694	        let mut slots: Vec<CudaSlice<bf16>> = initial
695	            .iter()
696	            .map(|values| ctx.stream.clone_htod(values))
697	            .collect::<std::result::Result<_, _>>()?;
698	
699	        let mut pointers = Vec::with_capacity(batch_size);
700	        for slot in &mut slots {
701	            let (pointer, _guard) = slot.device_ptr_mut(&ctx.stream);
702	            pointers.push(pointer);
703	        }
704	        let state_ptrs = ctx.stream.clone_htod(&pointers)?;
705	
706	        for step in 0..kernel_size + 2 {
707	            let row = bf16_vec(
708	                &(0..num_channels)
709	                    .map(|i| (((i * 13 + step * 29) % 101) as f32 - 50.0) * 0.007_812_5)
710	                    .collect::<Vec<_>>(),
711	            );
712	            let x_host: Vec<bf16> = (0..batch_size).flat_map(|_| row.clone()).collect();
713	            let x = HiddenStates {
714	                data: ctx.stream.clone_htod(&x_host)?,
715	                hidden_dim: num_channels,
716	                seq_len: batch_size,
717	            };
718	            let mut out = HiddenStates::zeros(&ctx, num_channels, batch_size)?;
719	            conv1d_decode_batch_into(&ctx, &x, &conv_weight, &state_ptrs, &mut out, kernel_size);
720	            ctx.sync()?;
721	
722	            let got: Vec<bf16> = ctx.stream.clone_dtoh(&out.data)?;
723	            for slot in 0..batch_size {
724	                let expected = reference_conv1d_decode_step(&row, &w_host, &mut host_states[slot]);
725	                let got_row = &got[slot * num_channels..(slot + 1) * num_channels];
726	                assert!(
727	                    got_row
728	                        .iter()
729	                        .chain(&expected)
730	                        .all(|value| value.to_f32().is_finite()),
731	                    "conv1d decode step {step} slot {slot}: non-finite output"
732	                );
733	                let max_ulps = got_row
734	                    .iter()
735	                    .zip(&expected)
736	                    .map(|(got, expected)| bf16_ulp_distance(*got, *expected))
737	                    .max()
738	                    .unwrap_or_default();
739	                assert!(
740	                    max_ulps <= 1,
741	                    "conv1d decode step {step} slot {slot}: output off by {max_ulps} bf16 ulps"
742	                );
743	            }
744	
745	            // The state is the previous inputs oldest-first, bit for bit.
746	            for (slot, values) in slots.iter().enumerate() {
747	                let device: Vec<bf16> = ctx.stream.clone_dtoh(values)?;
748	                ctx.sync()?;
749	                let expected: Vec<bf16> = host_states[slot]
750	                    .iter()
751	                    .map(|value| bf16::from_f32(*value))
752	                    .collect();
753	                assert_eq!(
754	                    device, expected,
755	                    "conv1d decode step {step} slot {slot}: state"
756	                );
757	            }
758	        }
759	        Ok(())
760	    }
