1056	    /// One band per projection, laid side by side in every slot of one fused
1057	    /// tensor, against the same values in their own buffers.
1058	    fn fused_and_separate(
1059	        ctx: &DeviceContext,
1060	        batch_size: usize,
1061	        widths: &[usize],
1062	        values: &[Vec<bf16>],
1063	    ) -> (HiddenStates, Vec<HiddenStates>) {
1064	        let total: usize = widths.iter().sum();
1065	        let mut fused = vec![bf16::ZERO; batch_size * total];
1066	        for slot in 0..batch_size {
1067	            let mut col = 0;
1068	            for (width, part) in widths.iter().zip(values) {
1069	                let row = &part[slot * width..(slot + 1) * width];
1070	                fused[slot * total + col..slot * total + col + width].copy_from_slice(row);
1071	                col += width;
1072	            }
1073	        }
1074	        let separate = widths
1075	            .iter()
1076	            .zip(values)
1077	            .map(|(width, part)| HiddenStates {
1078	                data: ctx.stream.clone_htod(part).expect("part H2D"),
1079	                hidden_dim: *width,
1080	                seq_len: batch_size,
1081	            })
1082	            .collect();
1083	        (
1084	            HiddenStates {
1085	                data: ctx.stream.clone_htod(&fused).expect("fused H2D"),
1086	                hidden_dim: total,
1087	                seq_len: batch_size,
1088	            },
1089	            separate,
1090	        )
1091	    }
